inputs.text:
# Week 1
## ME Upper
// Work up to a heavy 1-3RM, then one backoff AMRAP at ~70%.
me_upper[1-3] / used: none / 1x1-3, 1x3 / warmup: none / 180s / progress: custom() {~
  if (completedReps >= reps && week == 3 && dayInWeek == 1) {
    rm1 += 5lb
  }
~} / update: custom() {~
  if (setIndex == 1) {
    weights[2] = completedWeights[1] * 0.7
  }
~}

// ...me_upper
me_upper: Bench Press Close Grip / ...me_upper

me_acc: Incline Bench Press, Dumbbell[1-3] / 4x8 25lb / progress: dp(5lb, 8, 12)
me_acc: Bent Over Row[1-3] / 4x8 95lb / progress: dp(5lb, 8, 12)
me_acc: Triceps Pushdown[1-3] / 3x12 40lb / progress: dp(5lb, 12, 20)
me_acc: Face Pull[1-3] / 3x15 30lb / warmup: none / progress: dp(5lb, 15, 25)
me_acc: Hanging Leg Raise[1-3] / 3x12 0lb / warmup: none

## ME Lower
// Work up to a heavy 1-3RM, then one backoff AMRAP at ~70%.
me_lower[1-3] / used: none / 1x1-3, 1x3 / warmup: none / 180s / progress: custom() {~
  if (completedReps >= reps && week == 3 && dayInWeek == 2) {
    rm1 += 10lb
  }
~} / update: custom() {~
  if (setIndex == 1) {
    weights[2] = completedWeights[1] * 0.7
  }
~}


// ...me_lower
me_lower: Front Squat / ...me_lower

me_acc: Romanian Deadlift, Barbell[1-3] / 4x8 95lb / progress: dp(5lb, 8, 12)
me_acc: Lying Leg Curl[1-3] / 4x10 60lb / progress: dp(5lb, 10, 15)
me_acc: Lat Pulldown[1-3] / 3x10 70lb / progress: dp(5lb, 10, 15)
me_acc: Ab Wheel[1-3] / 3x10 0lb / warmup: none

## DE Upper
// Speed work. Move the bar as fast as possible. Rotate grip every 3 sets: close, medium, wide.
de: Bench Press / 3x3 (Close), 3x3 (Med), 3x3 (Wide) / 55% / 60s / warmup: none / progress: custom() {~
  if (week == 3) {
    rm1 += 5lb
  }
~}


de_acc: Overhead Press, Dumbbell[1-3] / 3x15 20lb / progress: dp(5lb, 15, 20)
de_acc: Triceps Extension[1-3] / 3x15 15lb / progress: dp(5lb, 15, 20)
de_acc: Seated Row[1-3] / 3x15 60lb / progress: dp(5lb, 15, 20)
de_acc: Lateral Raise[1-3] / 3x15 10lb / warmup: none / progress: dp(5lb, 15, 25)
de_acc: Hanging Leg Raise[1-3] / 3x15 0lb / warmup: none

## DE Lower

// Speed box squats. Sit back, pause briefly on the box, then explode up.
de: Box Squat / 10x2 / 60% / 60s / progress: custom() {~
  if (week == 3) {
    rm1 += 10lb
  }
~}

// Speed deadlifts. Each rep from a dead stop. Maximum acceleration off the floor.
de: Deadlift / 6x1 / 65% / 60s / warmup: none / progress: custom() {~
  if (week == 3) {
    rm1 += 10lb
  }
~}

de_acc: Leg Press[1-3] / 3x15 180lb / progress: dp(10lb, 15, 20)
de_acc: Lying Leg Curl[1-3] / 3x15 45lb / progress: dp(5lb, 15, 20)
de_acc: Bent Over Row[1-3] / 3x12 75lb / progress: dp(5lb, 12, 20)
de_acc: Hanging Leg Raise[1-3] / 3x20 0lb / warmup: none


# Week 2
## ME Upper
// ...me_upper
me_upper: Incline Bench Press / ...me_upper

## ME Lower
// ...me_lower
me_lower: Deficit Deadlift / ...me_lower

## DE Upper
de: Bench Press / 3x3 (Close), 3x3 (Med), 3x3 (Wide) / 60% / 60s

## DE Lower
de: Box Squat / 10x2 / 65% / 60s
de: Deadlift / 6x1 / 70% / 60s


# Week 3
## ME Upper
// ...me_upper
me_upper: Bench Press / ...me_upper

## ME Lower
// ...me_lower
me_lower: Good Morning / ...me_lower

## DE Upper
de: Bench Press / 3x3 (Close), 3x3 (Med), 3x3 (Wide) / 65% / 60s

## DE Lower
de: Box Squat / 10x2 / 70% / 60s
de: Deadlift / 6x1 / 75% / 60s

